package org.slavicmyths.verify;
import java.util.*;import java.nio.file.*;import java.util.concurrent.*;
import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.structure.*;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
import org.slavicmyths.chud.*;
/** Equal four-region new-world sample. Prediction selects exploration only; native FULL must independently agree. */
@EventBusSubscriber(modid="slavicmyths") public final class Census300 {
 static ServerLevel w;static long began,pre,since,requested;static boolean done;static int region,index,phase;static ChunkPos waiting;static ChudRegionPlanner.Selected site;static StructureStart start;
 static final int[][] REGIONS={{0,0},{1,0},{0,1},{1,1}};
 static final TicketType<Long> TICKET=TicketType.create("qa300_census",Long::compare);
 static final ExecutorService WORK=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"qa300-census");t.setDaemon(true);return t;});static Future<Optional<ChudRegionPlanner.Selected>> pending;
 static final List<Map<String,Object>> rows=new ArrayList<>();static final List<Long> times=new ArrayList<>();static Map<String,Object> row;static final List<ChunkPos> chunks=new ArrayList<>(),held=new ArrayList<>();static BoundingBox box;static long forecastAt;static int forecastLoaded,forecastRecords;static Capture capture;
 static final class Capture implements net.minecraft.commands.CommandSource {final List<String> messages=new ArrayList<>();public void sendSystemMessage(net.minecraft.network.chat.Component c){messages.add(c.getString());System.out.println("QA300_COMMAND "+c.getString());}public boolean acceptsSuccess(){return true;}public boolean acceptsFailure(){return true;}public boolean shouldInformAdmins(){return false;}}

 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!"census".equals(System.getProperty("slavicmyths.qa300")))return;w=e.getServer().overworld();began=System.nanoTime();region=Integer.getInteger("slavicmyths.qa300.firstRegion",0);try{var saved=Path.of("census300.json");if(Files.exists(saved)){var n=com.google.gson.JsonParser.parseString(Files.readString(saved)).getAsJsonObject();for(var value:n.getAsJsonArray("samples")){var item=value.getAsJsonObject();if(!item.get("status").getAsString().startsWith("PASS"))break;rows.add(new com.google.gson.Gson().fromJson(item,new com.google.gson.reflect.TypeToken<Map<String,Object>>(){}.getType()));region++;}System.out.println("QA300_RESUME completed regions="+region);}}catch(Exception x){throw new IllegalStateException("invalid QA resume",x);}}
 @SubscribeEvent public static void pre(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(w==null||done)return;times.add(System.nanoTime()-pre);try{
  if(System.nanoTime()-began>3_600_000_000_000L)throw new IllegalStateException("60 minute sample bound");
  if(region==REGIONS.length){finish(null);return;}
  if(phase==0){if(pending==null){since=System.nanoTime();row=new LinkedHashMap<>();row.put("region",List.of(REGIONS[region][0],REGIONS[region][1]));row.put("first_choice",ChudRegionPlanner.cityFirst(w.getSeed(),REGIONS[region][0],REGIONS[region][1])?"city":"abandoned");var g=w.getChunkSource().getGenerator();var c=new Structure.GenerationContext(w.registryAccess(),g,g.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),new ChunkPos(REGIONS[region][0]*256,REGIONS[region][1]*256),w,b->true);pending=WORK.submit(()->{ChudSearchBudget.begin(System.nanoTime()+600_000_000_000L);try{return ChudRegionPlanner.select(c);}finally{ChudSearchBudget.end();}});return;}if(!pending.isDone())return;var answer=pending.get();pending=null;row.put("planning_ms",(System.nanoTime()-since)/1e6);if(answer.isEmpty()){row.put("type","NONE");var g=w.getChunkSource().getGenerator();var context=new Structure.GenerationContext(w.registryAccess(),g,g.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),new ChunkPos(REGIONS[region][0]*256,REGIONS[region][1]*256),w,b->true);chunks.addAll(ChudRegionPlanner.placement(context).candidates(w.getSeed(),context.chunkPos().x,context.chunkPos().z));phase=4;return;}site=answer.get();row.put("owner",List.of(site.owner().x,site.owner().z));row.put("type",site.city()==null?site.abandoned().kind.toString():"city");row.put("attached",site.city()!=null&&site.abandoned()!=null);row.put("variant",site.city()!=null?site.city().variant:site.abandoned().shaftProfile);row.put("mouth",site.access().mouth.toShortString());row.put("distance_spawn",Math.sqrt(site.access().mouth.distSqr(w.getSharedSpawnPos())));capture=new Capture();forecastAt=w.getGameTime();forecastLoaded=w.getChunkSource().getLoadedChunksCount();forecastRecords=org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().size();var source=w.getServer().createCommandSourceStack().withLevel(w).withSource(capture).withPosition(new net.minecraft.world.phys.Vec3(site.owner().getMiddleBlockX(),70,site.owner().getMiddleBlockZ()));w.getServer().getCommands().performPrefixedCommand(source,"locate structure slavicmyths:chud_"+(site.city()!=null?"city":"abandoned"));phase=5;return;}
  if(phase==5){if(w.getGameTime()-forecastAt<40)return;row.put("before_exploration_command",List.copyOf(capture.messages));row.put("forecast_loaded_before",forecastLoaded);row.put("forecast_loaded_after",w.getChunkSource().getLoadedChunksCount());row.put("actual_site_tickets_after_search",TicketEvidence300.siteBuild(w));row.put("forecast_records_unchanged",forecastRecords==org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().size());boolean answer=capture.messages.stream().anyMatch(m->m.contains("НЕ FOUND_PHYSICAL")||m.contains("существующая структура")||m.contains("native start")||m.contains("native план"));if(!answer){if(w.getGameTime()-forecastAt<1300)return;throw new IllegalStateException("forecast never returned a verifiable result: "+capture.messages);}if(capture.messages.stream().anyMatch(m->m.contains("НЕ FOUND_PHYSICAL"))){int before=w.getChunkSource().getLoadedChunksCount();var control=new Capture();var source=w.getServer().createCommandSourceStack().withLevel(w).withSource(control).withPosition(new net.minecraft.world.phys.Vec3(site.owner().getMiddleBlockX(),70,site.owner().getMiddleBlockZ()));for(String command:List.of("slavicmyths dev "+(site.city()!=null?"city":"abandoned")+" search 0","slavicmyths chud_search status","slavicmyths chud_search cancel","slavicmyths chud_search next","slavicmyths chud_search cancel"))w.getServer().getCommands().performPrefixedCommand(source,command);row.put("cancel_next_commands",control.messages);row.put("cancel_next_loaded_unchanged",before==w.getChunkSource().getLoadedChunksCount());}chunks.add(site.owner());phase=1;return;}
  if(index<chunks.size()){var at=chunks.get(index);if(waiting==null){waiting=at;requested=System.nanoTime();w.getChunkSource().addRegionTicket(TICKET,at,0,300L);held.add(at);return;}var chunk=w.getChunkSource().getChunkNow(at.x,at.z);if(chunk==null){if(System.nanoTime()-requested>120_000_000_000L)throw new IllegalStateException("FULL timeout "+at);return;}waiting=null;index++;if(phase==4){for(var entry:chunk.getAllStarts().entrySet()){var id=w.registryAccess().registryOrThrow(Registries.STRUCTURE).getKey(entry.getKey());if(id!=null&&id.getNamespace().equals("slavicmyths")&&Set.of("chud_city","chud_abandoned").contains(id.getPath())&&entry.getValue().isValid())throw new IllegalStateException("rejected plan actually generated a root");}return;}if(phase==1){var reg=w.registryAccess().registryOrThrow(Registries.STRUCTURE);var type=reg.get(ResourceLocation.fromNamespaceAndPath("slavicmyths",site.city()==null?"chud_abandoned":"chud_city"));start=chunk.getStartForStructure(type);if(start==null||!start.isValid())throw new IllegalStateException("forecast has no actual native start");row.put("native_pieces",start.getPieces().size());box=start.getBoundingBox();row.put("bbox",List.of(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()));
    // Explore every physical construction column, not 289 empty rectangle corners.
    var needed=new LinkedHashSet<ChunkPos>();needed.add(site.owner());for(var piece:start.getPieces()){var fills=piece instanceof ChudPiece c?c.blueprint():piece instanceof AbandonedPiece a?a.blueprint():piece instanceof ChudAccessPiece a?a.access.blueprint():List.<ChudGeometry.Fill>of();for(var f:fills){var b=f.box();for(int x=b.minX()>>4;x<=b.maxX()>>4;x++)for(int z=b.minZ()>>4;z<=b.maxZ()>>4;z++)needed.add(new ChunkPos(x,z));}}row.put("occupied_chunks",needed.size());row.put("bbox_chunks",((box.maxX()>>4)-(box.minX()>>4)+1)*((box.maxZ()>>4)-(box.minZ()>>4)+1));for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)needed.add(new ChunkPos(x,z));var generator=w.getChunkSource().getGenerator();var context=new Structure.GenerationContext(w.registryAccess(),generator,generator.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),site.owner(),w,b->true);needed.addAll(ChudRegionPlanner.placement(context).candidates(w.getSeed(),site.owner().x,site.owner().z));chunks.clear();chunks.addAll(needed);index=1;phase=2;}return;}
  if(phase==4){row.put("status","PASS_NATURAL_REJECTION");row.put("accepted_roots",0);complete();return;}if(phase==2){phase=3;requested=w.getGameTime();return;}
  if(w.getGameTime()-requested<200)return;var population=org.slavicmyths.underground.EncounterPopulation.data(w).save(new net.minecraft.nbt.CompoundTag(),w.registryAccess());boolean ownPending=false;for(var tag:population.getList("Pending",10))if(((net.minecraft.nbt.CompoundTag)tag).getString("Key").contains(site.city()!=null?site.city().cityId():site.abandoned().rootId))ownPending=true;if(ownPending&&w.getGameTime()-requested<3600)return;inspect();complete();
 }catch(Throwable x){finish(x);}}
 static void inspect(){int roots=0;for(var at:chunks)for(var entry:w.getChunkSource().getChunkNow(at.x,at.z).getAllStarts().entrySet())if(entry.getValue().isValid()&&(entry.getKey() instanceof ChudStructure||entry.getKey() instanceof AbandonedStructure))roots++;row.put("accepted_roots",roots);if(roots!=1)throw new IllegalStateException("more than one native root "+roots);depth();var targets=new LinkedHashMap<String,BlockPos>();if(site.city()!=null){site.city().points.forEach((k,v)->targets.put(k.toString(),site.city().world(v)));row.put("city_internal",ChudNavigation.inspect(w,site.city()));}if(site.abandoned()!=null)site.abandoned().targets.forEach((k,v)->{if(!k.equals("sealed_lower_gate"))targets.put("AB:"+k,site.abandoned().world(v));});
  var nav=ChudNavigation.inspect(w,box,site.access().mouth,targets);row.put("surface_to_zones",nav);row.put("biome",w.getBiome(site.access().mouth).unwrapKey().orElseThrow().location().toString());row.put("mouth_block",w.getBlockState(site.access().mouth).toString());row.put("minBuildHeight",w.getMinBuildHeight());row.put("actual_city_people",w.getEntitiesOfClass(org.slavicmyths.industry.ChudPerson.class,net.minecraft.world.phys.AABB.of(box),x->true).size());row.put("encounters",org.slavicmyths.underground.EncounterPopulation.data(w).save(new net.minecraft.nbt.CompoundTag(),w.registryAccess()).toString());
  var mobs=new ArrayList<Map<String,Object>>();for(var mob:w.getEntitiesOfClass(org.slavicmyths.underground.EncounterMob.class,net.minecraft.world.phys.AABB.of(box),x->true))mobs.add(Map.of("id",BuiltInRegistries.ENTITY_TYPE.getKey(mob.getType()).toString(),"uuid",mob.getUUID().toString(),"pos",mob.blockPosition().toShortString()));row.put("actual_underground_mobs",mobs);
  var ownerChunk=w.getChunkSource().getChunkNow(site.owner().x,site.owner().z);int before=org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().size();int records=before;var source=w.getServer().createCommandSourceStack().withLevel(w).withPosition(net.minecraft.world.phys.Vec3.atCenterOf(site.access().mouth));long t=System.nanoTime();for(String cmd:List.of("locate structure slavicmyths:chud_"+(site.city()!=null?"city":"abandoned"),"slavicmyths dev "+(site.city()!=null?"city":"abandoned")+" locate"))w.getServer().getCommands().performPrefixedCommand(source,cmd);row.put("locate_ms",(System.nanoTime()-t)/1e6);row.put("locate_records_unchanged",records==org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().size());row.put("status",nav.status().equals("PASS")?"PASS_BLOCK_PATH_ONLY":"FAIL_BLOCK_PATH");
 }
 static void depth(){
  var fills=new ArrayList<ChudGeometry.Fill>();for(var p:start.getPieces()){if(p instanceof ChudPiece city)fills.addAll(city.blueprint());if(p instanceof AbandonedPiece abandoned)fills.addAll(abandoned.blueprint());}
  var roofs=new HashMap<Long,Integer>();int min=Integer.MAX_VALUE,top=Integer.MIN_VALUE;
  for(var f:fills){var b=f.box();min=Math.min(min,b.minY());top=Math.max(top,b.maxY());if(f.state().isAir())continue;for(int x=b.minX();x<=b.maxX();x++)for(int z=b.minZ();z<=b.maxZ();z++)roofs.merge(net.minecraft.core.BlockPos.asLong(x,0,z),b.maxY(),Math::max);}
  int cover=Integer.MAX_VALUE,groundMin=Integer.MAX_VALUE,groundMax=Integer.MIN_VALUE;BlockPos worst=BlockPos.ZERO;for(var entry:roofs.entrySet()){var p=BlockPos.of(entry.getKey());int ground=org.slavicmyths.worldgen.LandTerrain.ground(w,p.getX(),p.getZ());groundMin=Math.min(groundMin,ground);groundMax=Math.max(groundMax,ground);if(ground-entry.getValue()<cover){cover=ground-entry.getValue();worst=p.atY(entry.getValue());}}
  row.put("depth",Map.of("min_construction_y",min,"top_roof_y",top,"min_ground_y",groundMin,"max_ground_y",groundMax,"minimum_roof_cover_actual",cover,"worst_roof",worst.toShortString(),"min_build_height",w.getMinBuildHeight(),"mouth_y",site.access().mouth.getY()));
  if(min<w.getMinBuildHeight()+6||cover<20)throw new IllegalStateException("actual depth failed: "+row.get("depth"));
 }
 static void complete(){row.put("full_construction_chunks",index);row.put("elapsed_s",(System.nanoTime()-since)/1e9);rows.add(row);System.out.println("QA300_CENSUS "+new com.google.gson.Gson().toJson(row));release();chunks.clear();index=phase=0;site=null;start=null;region++;write(null);}
 static void release(){for(var p:held)w.getChunkSource().removeRegionTicket(TICKET,p,0,300L);held.clear();waiting=null;}
 static void write(Throwable x){var out=new LinkedHashMap<String,Object>();out.put("seed",w.getSeed());out.put("samples",rows);out.put("error",x==null?null:x.toString());out.put("elapsed_s",(System.nanoTime()-began)/1e9);var sorted=new ArrayList<>(times);Collections.sort(sorted);out.put("p95_ms",sorted.isEmpty()?0:sorted.get((int)(sorted.size()*.95))/1e6);out.put("max_ms",sorted.isEmpty()?0:sorted.getLast()/1e6);out.put("player_walk_relog_client","NOT_RUN by this dedicated observation");try{Files.writeString(Path.of("census300.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));}catch(Exception ex){throw new RuntimeException(ex);}}
 static void finish(Throwable x){done=true;if(x!=null){x.printStackTrace();if(row!=null){row.put("status","FAIL_OR_UNKNOWN");row.put("error",x.toString());rows.add(row);}}WORK.shutdownNow();release();write(x);w.getServer().saveEverything(false,true,true);w.getServer().halt(false);}
}
